<?php
require __DIR__.'/../includes/config.php';require __DIR__.'/../includes/functions.php';$u=require_role(['operator']);
$status=$_GET['status']??'';$cat=(int)($_GET['category']??0);$township=trim($_GET['township']??'');$where=[];$args=[];if($status!==''&&ctype_digit((string)$status)&&$status>=0&&$status<=4){$where[]='r.status=?';$args[]=(int)$status;}if($cat){$where[]='r.category_id=?';$args[]=$cat;}if($township!==''){$where[]='r.township=?';$args[]=$township;}$sql='SELECT r.*,c.name category_name,u.full_name owner_name FROM requests r JOIN categories c ON c.id=r.category_id JOIN users u ON u.id=r.owner_id'.($where?' WHERE '.implode(' AND ',$where):'').' ORDER BY r.created_at DESC';$st=$pdo->prepare($sql);$st->execute($args);$rows=$st->fetchAll();$cats=category_rows($pdo);$townships=$pdo->query('SELECT DISTINCT township FROM requests ORDER BY township')->fetchAll(PDO::FETCH_COLUMN);$pageTitle='Incoming Requests';require __DIR__.'/../includes/header.php';?>
<div class="eyebrow">OPERATOR WORKSPACE</div><h2>Incoming <span class="red">Requests</span></h2><p class="subtext">Filter by status, issue category and township. Open a request to assign a provider and update its status.</p><div class="card"><form method="get" class="form-row" style="align-items:end"><div class="field"><label>Status</label><select name="status"><option value="">All statuses</option><?php foreach(status_names() as $i=>$s):?><option value="<?=$i?>" <?=((string)$i===$status)?'selected':''?>><?=e($s)?></option><?php endforeach;?></select></div><div class="field"><label>Category</label><select name="category"><option value="0">All categories</option><?php foreach($cats as $c):?><option value="<?=$c['id']?>" <?=$cat===$c['id']?'selected':''?>><?=e($c['name'])?></option><?php endforeach;?></select></div><div class="field"><label>Township</label><select name="township"><option value="">All townships</option><?php foreach($townships as $t):?><option <?=($township===$t?'selected':'')?>><?=e($t)?></option><?php endforeach;?></select></div><div class="field"><button class="btn btn-primary btn-block">Apply filters</button></div></form></div><div class="card" style="margin-top:15px"><div class="table-wrap"><table class="table"><thead><tr><th>Reference</th><th>Owner</th><th>Category / issue</th><th>Township</th><th>Status</th><th>Created</th><th></th></tr></thead><tbody><?php if(!$rows):?><tr><td colspan="7" class="empty">No requests match these filters.</td></tr><?php endif;foreach($rows as $r):?><tr><td><strong><?=e($r['request_no'])?></strong></td><td><?=e($r['owner_name'])?></td><td><?=e($r['category_name'])?><br><small class="muted"><?=e($r['title'])?></small></td><td><?=e($r['township'])?></td><td><span class="badge <?=status_class((int)$r['status'])?>"><?=e(status_names()[$r['status']])?></span></td><td><?=e(date('d M, g:i A',strtotime($r['created_at'])))?></td><td><a class="btn btn-secondary btn-sm" href="<?=BASE_URL?>/operator/request.php?id=<?=$r['id']?>">Manage</a></td></tr><?php endforeach;?></tbody></table></div></div><?php require __DIR__.'/../includes/footer.php';?>
